python3 << 'EOF'
import json

with open('/logs/agent/output.json', 'r') as f:
    data = json.load(f)

# Comprehensive validation
errors = []

# 1. Check top-level keys
required_keys = {'artifact_audits', 'shard_summaries', 'summary'}
if set(data.keys()) != required_keys:
    errors.append(f"Wrong top-level keys: {set(data.keys())}")

# 2. Check artifact_audits
if len(data['artifact_audits']) != 20:
    errors.append(f"Expected 20 artifacts, got {len(data['artifact_audits'])}")

# 3. Check all artifacts have required fields
required_artifact_fields = {'artifact_id', 'problem_id', 'competition', 'year', 'central_technique', 'rigor_score', 'claim_audits'}
for art in data['artifact_audits']:
    if set(art.keys()) != required_artifact_fields:
        errors.append(f"artifact {art.get('artifact_id', '?')} has wrong fields: {set(art.keys())}")

    # Check rigor_score is 1-5
    if not 1 <= art['rigor_score'] <= 5:
        errors.append(f"artifact {art['artifact_id']} has invalid rigor_score: {art['rigor_score']}")

    # Check central_technique is valid
    valid_techniques = {
        'algebraic_manipulation', 'combinatorial_counting', 'induction', 
        'inequality_application', 'modular_arithmetic', 'geometric_construction',
        'extremal_principle', 'invariant_or_monovariant', 'generating_function',
        'proof_by_contradiction'
    }
    if art['central_technique'] not in valid_techniques:
        errors.append(f"artifact {art['artifact_id']} has invalid technique: {art['central_technique']}")

    # Check claim statuses
    valid_statuses = {'verified', 'unjustified', 'incorrect'}
    for claim in art['claim_audits']:
        if claim['status'] not in valid_statuses:
            errors.append(f"artifact {art['artifact_id']} claim {claim.get('claim_id', '?')} has invalid status: {claim['status']}")

# 4. Check shard_summaries
if len(data['shard_summaries']) != 5:
    errors.append(f"Expected 5 shards, got {len(data['shard_summaries'])}")

# 5. Check summary fields
summary = data['summary']
required_summary_fields = {
    'total_artifacts', 'total_claims', 'claim_status_counts', 'technique_counts',
    'mean_rigor', 'competition_counts', 'year_counts', 'artifacts_by_technique'
}
if set(summary.keys()) != required_summary_fields:
    errors.append(f"summary has wrong fields: {set(summary.keys())}")

# 6. Verify technique_counts sum
if sum(summary['technique_counts'].values()) != 20:
    errors.append(f"technique_counts sum != 20: {sum(summary['technique_counts'].values())}")

# 7. Verify competition_counts sum
if sum(summary['competition_counts'].values()) != 20:
    errors.append(f"competition_counts sum != 20: {sum(summary['competition_counts'].values())}")

# 8. Verify year_counts sum
if sum(summary['year_counts'].values()) != 20:
    errors.append(f"year_counts sum != 20: {sum(summary['year_counts'].values())}")

if errors:
    print("ERRORS FOUND:")
    for e in errors:
        print(f"  - {e}")
else:
    print("ALL VALIDATIONS PASSED!")
    print(f"  - 20 artifacts audited")
    print(f"  - {summary['total_claims']} total claims")
    print(f"  - Claim status: {summary['claim_status_counts']}")
    print(f"  - Mean rigor: {summary['mean_rigor']}")
EOF
